// ═══════════════════════════════════════════════════════════════════════
//  CENTRAL DE AUTOMAÇÃO — BLOQUEADA
//
//  Este arquivo substitui o central.js de verdade enquanto a ferramenta
//  estiver fora do ar. Quem clicar no favorito Robôs vê o aviso "A CASA
//  CAIU!" em tela cheia, com um botão Encerrar. A Central NÃO abre.
//
//  PARA LIBERAR DE NOVO: cole o conteúdo do central.js que funciona por
//  cima deste arquivo, aqui no GitHub. Volta na hora, para todo mundo.
//
//  A imagem está embutida aqui dentro, então o aviso aparece até nos
//  portais que proíbem buscar imagem de fora.
// ═══════════════════════════════════════════════════════════════════════
(() => {
    if (document.getElementById('cr-casa-caiu')) return;

    const IMAGEM = "data:image/webp;base64,";

    const rolagemAntes = document.body ? document.body.style.overflow : '';

    const fundo = document.createElement('div');
    fundo.id = 'cr-casa-caiu';
    fundo.style.cssText = [
        'position:fixed', 'top:0', 'left:0', 'right:0', 'bottom:0',
        'z-index:2147483647',
        'background:rgba(8,10,14,.92)',
        'display:flex', 'flex-direction:column',
        'align-items:center', 'justify-content:center',
        'gap:20px', 'padding:24px',
        'font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif'
    ].join(';');

    const figura = document.createElement('img');
    figura.src = IMAGEM;
    figura.alt = 'A casa caiu! Este programa está bloqueado no momento.';
    figura.style.cssText = [
        'max-width:min(1100px,92vw)', 'max-height:74vh',
        'width:auto', 'height:auto',
        'border-radius:14px',
        'box-shadow:0 24px 70px rgba(0,0,0,.6)',
        'display:block'
    ].join(';');

    // Se a imagem não carregar por qualquer motivo, o recado aparece em texto.
    const textoReserva = document.createElement('div');
    textoReserva.style.cssText = 'display:none;color:#fff;text-align:center;max-width:520px;';
    textoReserva.innerHTML = '<div style="font-size:44px;line-height:1;margin-bottom:14px;">🔒</div>' +
        '<div style="font-size:26px;font-weight:800;margin-bottom:8px;">A CASA CAIU!</div>' +
        '<div style="font-size:17px;">Este programa está bloqueado no momento.</div>' +
        '<div style="font-size:14px;color:#9aa4b2;margin-top:8px;">Tente novamente mais tarde ' +
        'ou entre em contato com o suporte.</div>';
    figura.onerror = () => {
        try { figura.style.display = 'none'; textoReserva.style.display = 'block'; } catch (e) { }
    };

    const botao = document.createElement('button');
    botao.type = 'button';
    botao.textContent = 'Encerrar';
    botao.style.cssText = [
        'padding:14px 48px',
        'border:none', 'border-radius:11px',
        'background:#e53935', 'color:#fff',
        'font-size:17px', 'font-weight:700',
        'font-family:inherit',
        'cursor:pointer',
        'box-shadow:0 8px 24px rgba(229,57,53,.35)'
    ].join(';');
    botao.onmouseenter = () => { botao.style.background = '#c62828'; };
    botao.onmouseleave = () => { botao.style.background = '#e53935'; };

    const fechar = () => {
        try { document.removeEventListener('keydown', aoTeclar, true); } catch (e) { }
        try { fundo.remove(); } catch (e) { }
        try { if (document.body) document.body.style.overflow = rolagemAntes; } catch (e) { }
    };
    const aoTeclar = ev => { if (ev.key === 'Escape') fechar(); };

    botao.onclick = fechar;
    document.addEventListener('keydown', aoTeclar, true);

    fundo.appendChild(figura);
    fundo.appendChild(textoReserva);
    fundo.appendChild(botao);

    try {
        (document.body || document.documentElement).appendChild(fundo);
        if (document.body) document.body.style.overflow = 'hidden';
    } catch (e) {
        alert('A CASA CAIU! Este programa está bloqueado no momento.');
        return;
    }

    try { botao.focus(); } catch (e) { }
    try { console.warn('[Central de Automação] Bloqueada temporariamente.'); } catch (e) { }
})();
